    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    def edge_runs(row):
        runs = []
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            color, start = row[c], c
            while c < w and row[c] == color:
                c += 1
            if c - start >= 2:
                runs.append((start, c - 1, color))
        return runs

    pairs = []
    for top in edge_runs(grid[0]):
        for bottom in edge_runs(grid[-1]):
            if top[2] == bottom[2] and top[1] - top[0] == bottom[1] - bottom[0]:
                pairs.append((top, bottom))

    markers = []
    for r in range(1, h - 1):
        for c in range(w):
            if grid[r][c] == bg:
                continue
            for top, bottom in pairs:
                if top[0] <= c <= top[1]:
                    markers.append((r, c, grid[r][c], top, bottom, True))
                    break
                if bottom[0] <= c <= bottom[1]:
                    markers.append((r, c, grid[r][c], top, bottom, False))
                    break

    marker_cells = {(r, c) for r, c, *_ in markers}

    def paint_if_background(r, c, color):
        if out[r][c] == bg:
            out[r][c] = color

    for r, c, color, top, bottom, on_top in markers:
        if on_top:
            offset = c - top[0]
            partner_c = bottom[0] + offset
            # Extend the marker's ray to the top edge.
            for rr in range(r):
                paint_if_background(rr, c, color)
        else:
            offset = c - bottom[0]
            partner_c = top[0] + offset
            # Extend the marker's ray to the bottom edge.
            for rr in range(r + 1, h):
                paint_if_background(rr, c, color)

        # Project the corresponding ray from the opposite edge.
        for rr in range(h):
            paint_if_background(rr, partner_c, color)

    for r, c in marker_cells:
        out[r][c] = 4
    return out
